import type { Resource } from 'qortex-resource';
import { useField } from 'qortex-resource-react';

export function TextField({
  resource,
  path,
  label,
  type = 'text',
}: {
  resource: Resource<any>;
  path: string;
  label: string;
  type?: string;
}) {
  const { value, error, isChanged, onChange, onBlur } = useField(resource, path);

  return (
    <label style={{ display: 'block', marginBottom: 12 }}>
      <span>{label}{isChanged ? ' *' : ''}</span>
      <input
        type={type}
        value={(value as string | number | undefined) ?? ''}
        onChange={(e) =>
          onChange(type === 'number' ? Number(e.target.value) : e.target.value)
        }
        onBlur={onBlur}
        aria-invalid={!!error}
      />
      {error && <span role="alert">{error}</span>}
    </label>
  );
}

function SaveBar({
  isChanged,
  isValid,
  isSaving,
  onSave,
  onReset,
}: {
  isChanged: boolean;
  isValid: boolean;
  isSaving: boolean;
  onSave: () => void;
  onReset: () => void;
}) {
  if (!isChanged) return null;

  return (
    <div role="status" style={{ position: 'sticky', bottom: 0, padding: 12 }}>
      <span>Unsaved changes</span>
      <button disabled={!isValid || isSaving} onClick={onSave}>
        {isSaving ? 'Saving…' : 'Save'}
      </button>
      <button type="button" onClick={onReset}>Discard</button>
    </div>
  );
}

function LoginForm() {
  const { resource, isSaving, isValid, save, mutation } = useResource({
    initialData: { email: '', password: '' },
    validate: {
      on: 'submit',
      fields: {
        email: (v) => (!v?.includes('@') ? 'Enter a valid email' : null),
        password: (v) => (!v || v.length < 8 ? 'Min 8 characters' : null),
      },
    },
    source: {
      save: async (draft) => {
        await api.auth.login(draft);
        return draft;
      },
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        save();
      }}
    >
      <TextField resource={resource} path="email" label="Email" />
      <TextField resource={resource} path="password" label="Password" type="password" />
      {mutation.error && <p role="alert">{String(mutation.error)}</p>}
      <button disabled={!isValid || isSaving}>
        {isSaving ? 'Signing in…' : 'Sign in'}
      </button>
    </form>
  );
}

function Filters({ onApply }: { onApply: (f: Filters) => void }) {
  const { resource, draft, set } = useResource({
    initialData: { q: '', status: 'all' as 'all' | 'open' | 'closed' },
  });

  return (
    <div>
      <TextField resource={resource} path="q" label="Search" />
      <select
        value={draft?.status}
        onChange={(e) => set('status', e.target.value)}
      >
        <option value="all">All</option>
        <option value="open">Open</option>
        <option value="closed">Closed</option>
      </select>
      <button type="button" onClick={() => onApply(draft!)}>Apply</button>
    </div>
  );
}

